#!/bin/bash
U=http://127.0.0.1/project/edu/app; P=0; F=0
ok(){ if [ "$2" = "1" ]; then P=$((P+1)); echo "  ✓ $1"; else F=$((F+1)); echo "  ❌ $1"; fi; }
J(){ php -r '$j=json_decode(stream_get_contents(STDIN),true); $k=explode(".",$argv[1]); foreach($k as $x){ if(!is_array($j)||!array_key_exists($x,$j)){echo "";exit;} $j=$j[$x]; } echo is_bool($j)?($j?"true":"false"):(is_array($j)?json_encode($j):$j);' "$1"; }
rm -rf /var/www/html/project/edu/app/dati/rl /var/www/html/project/edu/app/dati/live/*.json
R=$(curl -s -X POST "$U/live.php?action=crea" -H 'Content-Type: application/json' -d '{"titolo":"Test","quiz":[{"domanda":"Capitale?","opzioni":["Roma","Parigi","Madrid"],"g":0,"spiegazione":"Roma è la capitale."},{"domanda":"2+2?","opzioni":["3","4"],"g":1}]}')
PIN=$(echo "$R"|J pin); HOST=$(echo "$R"|J host); ok "stanza creata con PIN a 6 cifre e token host" "$([ ${#PIN} = 6 ] && [ -n "$HOST" ] && echo 1)"
R=$(curl -s -X POST "$U/live.php?action=join" -H 'Content-Type: application/json' -d '{"pin":"000000","nome":"Anna"}'); ok "PIN inesistente → rifiutato ($(echo "$R"|J err))" "$([ -n "$(echo "$R"|J err)" ] && echo 1)"
R=$(curl -s -X POST "$U/live.php?action=join" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"nome\":\"Anna\"}"); TA=$(echo "$R"|J token); ok "Anna entra e riceve un token" "$([ -n "$TA" ] && echo 1)"
R=$(curl -s -X POST "$U/live.php?action=join" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"nome\":\"Anna\"}"); TA2=$(echo "$R"|J token); ok "secondo «Anna»: gestito senza errore (nome reso univoco o accettato) → $(echo "$R"|J nome)" "$([ -n "$TA2" ] && echo 1)"
R=$(curl -s -X POST "$U/live.php?action=join" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"nome\":\"<script>alert(1)</script>\"}"); ok "soprannome con HTML: ripulito → «$(echo "$R"|J nome)»" "$(echo "$R"|J nome | grep -qv '<' && echo 1)"
R=$(curl -s -X POST "$U/live.php?action=risposta" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"token\":\"$TA\",\"q\":0,\"r\":0}"); ok "risposta PRIMA che il docente apra la domanda → rifiutata ($(echo "$R"|J err))" "$([ -n "$(echo "$R"|J err)" ] && echo 1)"
R=$(curl -s -X POST "$U/live.php?action=avanza" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"host\":\"token-falso\"}"); ok "avanza con token host falso → rifiutato" "$([ -n "$(echo "$R"|J err)" ] && echo 1)"
R=$(curl -s -X POST "$U/live.php?action=avanza" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"host\":\"$HOST\"}"); ok "docente apre la domanda 1 (stato=domanda)" "$([ "$(echo "$R"|J stato)" = "domanda" ] && echo 1)"
R=$(curl -s "$U/live.php?action=stato&pin=$PIN&token=$TA"); ok "anti-cheat: l'alunno vede domanda e opzioni ma NON la risposta giusta" "$([ -n "$(echo "$R"|J domanda)" ] && [ -z "$(echo "$R"|J giusta)" ] && [ -z "$(echo "$R"|J g)" ] && echo 1)"
R=$(curl -s -X POST "$U/live.php?action=risposta" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"token\":\"$TA\",\"q\":0,\"r\":0}"); ok "Anna risponde (ok)" "$([ "$(echo "$R"|J ok)" = "true" ] && echo 1)"
R=$(curl -s -X POST "$U/live.php?action=risposta" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"token\":\"$TA\",\"q\":0,\"r\":1}"); ok "seconda risposta alla stessa domanda → ignorata, resta la prima (gia=true)" "$([ "$(echo "$R"|J gia)" = "true" ] && echo 1)"
R=$(curl -s -X POST "$U/live.php?action=risposta" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"token\":\"$TA2\",\"q\":0,\"r\":7}"); ok "indice di risposta fuori range → rifiutato" "$([ -n "$(echo "$R"|J err)" ] && echo 1)"
R=$(curl -s -X POST "$U/live.php?action=avanza" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"host\":\"$HOST\"}"); ok "docente chiude le risposte → stato=risultati con conteggi" "$([ "$(echo "$R"|J stato)" = "risultati" ] && echo 1)"
R=$(curl -s "$U/live.php?action=stato&pin=$PIN&token=$TA"); ok "ora l'alunno riceve giusta/sbagliata e la spiegazione «Lo sapevi?»" "$([ -n "$(echo "$R"|J giusta)" ] && echo "$R" | grep -q "Roma è la capitale" && echo 1)"
R=$(curl -s -X POST "$U/live.php?action=avanza" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"host\":\"$HOST\"}"); R=$(curl -s -X POST "$U/live.php?action=avanza" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"host\":\"$HOST\"}"); R=$(curl -s -X POST "$U/live.php?action=avanza" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"host\":\"$HOST\"}")
S=$(curl -s "$U/live.php?action=stato&pin=$PIN&token=$HOST"); ok "dopo l'ultima domanda → stato=fine, il docente riceve recap e pct_classe" "$([ "$(echo "$R"|J stato)" = "fine" ] && [ -n "$(echo "$S"|J pct_classe)" ] && echo 1)"
R=$(curl -s -X POST "$U/live.php?action=chiudi" -H 'Content-Type: application/json' -d "{\"pin\":\"$PIN\",\"host\":\"$HOST\"}"); R=$(curl -s "$U/live.php?action=stato&pin=$PIN&token=$TA"); ok "stanza chiusa: il polling dice che non esiste più" "$([ -n "$(echo "$R"|J err)" ] && echo 1)"
echo "RISULTATO: $P passati, $F falliti"
